import axios from 'axios';

const API_BASE = 'http://localhost:5000/api';

export const fetchIncidents = (params) =>
  axios.get(`${API_BASE}/incidents`, { params });

export const fetchIncidentById = (id) =>
  axios.get(`${API_BASE}/incidents/${id}`);

export const createIncident = (data) =>
  axios.post(`${API_BASE}/incidents`, data);

export const updateIncidentStatus = (id, status) =>
  axios.patch(`${API_BASE}/incidents/${id}/status`, { status });

export const addIncidentComment = (id, text) =>
  axios.post(`${API_BASE}/incidents/${id}/comments`, { text });
